import 'package:intl/intl.dart';
import '../models/finance_models.dart';
class FinanceSummary { const FinanceSummary({required this.income,required this.expenses,required this.payroll,required this.cogs}); final double income,expenses,payroll,cogs; double get operatingResult=>income-expenses-payroll-cogs; }
class FinanceCalculator { static FinanceSummary summarize({required List<IncomeEntry> income,required List<ExpenseRecord> expenses,required List<PayrollPayment> payroll,required List<StockCost> stockCosts}) { final i=income.fold<double>(0,(s,e)=>s+e.amount),x=expenses.fold<double>(0,(s,e)=>s+e.amount),p=payroll.fold<double>(0,(s,e)=>s+e.amount); final c=stockCosts.where((e)=>e.kind=='adjustment').fold<double>(0,(s,e)=>s+e.totalCost.abs()); return FinanceSummary(income:i,expenses:x,payroll:p,cogs:c); } static String money(num v)=>NumberFormat.currency(locale:'en_IN',symbol:'₹').format(v); }
